int copy_bitmap_file_to_user(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bfile;
    int err = 0;

    bfile = kmalloc(sizeof(*bfile), GFP_KERNEL);
    if (!bfile)
        return -ENOMEM;

    if (!mddev->bitmap) {
        bfile->pathname[0] = '\0';
    } else {
        char *path = mddev->bitmap->file->f_path.dentry->d_name.name;
        strncpy(bfile->pathname, path, sizeof(bfile->pathname) - 1);
        bfile->pathname[sizeof(bfile->pathname) - 1] = '\0';
    }

    if (copy_to_user(arg, bfile, sizeof(*bfile)))
        err = -EFAULT;

    kfree(bfile);
    return err;
}

int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file *bf;
    int ret = 0;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!mddev->bitmap) {
        bf->pathname[0] = '\0';
    } else {
        const char *path = mddev->bitmap->filename;

        if (strlen(path) >= BITMAP_PATH_MAX) {
            ret = -ENAMETOOLONG;
            goto out;
        }

        strcpy(bf->pathname, path);
    }

    if (copy_to_user(arg, bf, sizeof(*bf))) {
        ret = -EFAULT;
        goto out;
    }

out:
    kfree(bf);
    return ret;
}

int get_bitmap_file(struct mddev *mddev, void __user *arg)
{
    struct bitmap_file {
        char pathname[BDEVNAME_SIZE];
    } *bf;
    int ret = 0;

    bf = kmalloc(sizeof(*bf), GFP_KERNEL);
    if (!bf)
        return -ENOMEM;

    if (!test_bit(BitmapEnabled, &mddev->flags)) {
        /* Bitmap is disabled */
        bf->pathname[0] = '\0';
    } else {
        char *path;

        path = bdevname(mddev->bitmap->file->bdev, bf->pathname);
        if (!path) {
            ret = -EFAULT;
            goto out;
        }
    }

    if (copy_to_user(arg, bf, sizeof(*bf)))
        ret = -EFAULT;

out:
    kfree(bf);
    return ret;
}

